similarity &lt;- function(V, V0) {

  n_cols_v &lt;- ncol(V)
  n_cols_v0 &lt;- ncol(V0)
  result &lt;- matrix(0, nrow = n_cols_v, ncol = n_cols_v0)

  for (i in 1:n_cols_v) {
    for (j in 1:n_cols_v0) {
      result[i, j] &lt;- crossprod(V[ , i], V0[ , j]) /
        sqrt(crossprod(V[ , i]) * crossprod(V0[ , j]))
    }
  }

  return(result)

}


